// The Android app's own texts (strings.json, generated by scripts/gen_web_strings.js). One call per text, formatted like Android:
// S("chest_detail_gold", 150, 250) fills %1$d / %2$s / %%. The language is the game's (set by app.js through setLang).
let STR = null, L = "tr";
export const setLang = (l) => { L = l; };
export const getLang = () => L;
export async function loadStrings() { if (!STR) STR = await (await fetch("strings.json")).json(); }
export const ready = () => !!STR;
export function S(key, ...a) {
  const e = STR && STR[key]; if (!e) return key;
  // %1$d / %1$s plain, %1$,d grouped like the app ("6.245" / "6,245"), %1$.1f with that many decimals (comma in Turkish)
  return (e[L] || e.en || key).replace(/%(\d)\$(,|\.(\d))?([dsf])/g, (_, i, flag, prec) => {
    const v = a[+i - 1]; if (v == null) return "";
    if (flag === ",") return fmtNum(v);
    if (prec !== undefined) { const t = Number(v).toFixed(+prec); return L === "tr" ? t.replace(".", ",") : t; }
    return v;
  }).replace(/%%/g, "%");
}
/**
 * Makes [keys] ({ field: "app_string_key" }) of a screen's own word table ({ tr: {…}, en: {…} }) read the app's texts from
 * strings.json, so a text changed in the app changes here too; until strings.json is in, the table's own words stand.
 */
export function useAppTexts(table, keys) {
  for (const l of Object.keys(table)) for (const [k, key] of Object.entries(keys)) {
    const own = table[l][k];
    Object.defineProperty(table[l], k, { get: () => (STR && STR[key] ? STR[key][l] || STR[key].en : own), enumerable: true, configurable: true });
  }
}
/** A thousands-grouped number the way the app writes it in Turkish ("6.245") and English ("6,245"). */
export const fmtNum = (n) => Number(n).toLocaleString(L === "tr" ? "tr-TR" : "en-US");
